import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("claim templates", () => {
  test("claim templates", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-02-01", "to": "2026-02-10"})).toBe(true);
    expect(await ui.saveTemplate(pg_uma, {"name": "Fee", "amount": "12.50", "note": "fee"})).toBe(true);
    expect(await ui.saveTemplate(pg_uma, {"name": " ", "amount": "1.00", "note": ""})).toBe(false);
    expect(await ui.saveTemplate(pg_uma, {"name": "Bad", "amount": "1.005", "note": ""})).toBe(false);
    const c_ada_0 = ui.must(await ui.claimFromTemplate(pg_uma, p_ada, "Fee"));
    expect(await ui.saveTemplate(pg_uma, {"name": "Fee", "amount": "20.00", "note": "fee2"})).toBe(true);
    const c_ada_1 = ui.must(await ui.claimFromTemplate(pg_uma, p_ada, "Fee"));
    expect(await ui.claimFromTemplate(pg_uma, p_ada, "None")).toBeNull();
    await ui.setSetting(pg_uma, "entry-date", "2026-02-05");
    expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
    const c_ada_2 = ui.must(await ui.claimFromTemplate(pg_uma, p_ada, "Fee"));
    await ui.setSetting(pg_uma, "entry-date", "");
    const c_ada_3 = ui.must(await ui.claimFromTemplate(pg_uma, p_ada, "Fee"));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_2, "open")).toBe(true);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("52.50");
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("5.25");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_3).getByTestId("claim-amount")).toHaveText("20.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_3).getByTestId("claim-note")).toHaveText("fee2");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_3).getByTestId("claim-date")).toHaveText("2026-03-10");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_3).getByTestId("claim-due")).toHaveText("2.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_3).getByTestId("claim-status")).toHaveText("DRAFT");
