-- The sheet's void reasons, in the order added: while a sheet has any, a claim is voided only with
-- one of them. A reason is on a sheet's list at most once.
CREATE TABLE sheet_void_reason (
    sheet_id VARCHAR(200)  NOT NULL,
    reason   VARCHAR(200)  NOT NULL,
    position BIGINT        NOT NULL,
    PRIMARY KEY (sheet_id, reason)
);

CREATE TABLE asof.sheet_void_reason AS SELECT * FROM public.sheet_void_reason WHERE FALSE;
CREATE TABLE asof_hist.sheet_void_reason AS SELECT * FROM public.sheet_void_reason WHERE FALSE;
ALTER TABLE asof_hist.sheet_void_reason ADD COLUMN h_seq BIGINT NOT NULL;
ALTER TABLE asof_hist.sheet_void_reason ADD COLUMN h_made_on DATE;
ALTER TABLE asof_hist.sheet_void_reason ADD COLUMN h_op CHAR(1) NOT NULL;
CREATE INDEX sheet_void_reason_hist_sheet ON asof_hist.sheet_void_reason (sheet_id, h_seq);
CREATE TRIGGER sheet_void_reason_history AFTER INSERT, UPDATE, DELETE ON public.sheet_void_reason FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';

-- The reason a claim was voided with, from its sheet's list; null when none was given.
ALTER TABLE public.claim ADD COLUMN void_reason VARCHAR(200);
ALTER TABLE asof.claim ADD COLUMN void_reason VARCHAR(200);
ALTER TABLE asof_hist.claim ADD COLUMN void_reason VARCHAR(200);
-- The history trigger keeps the column list it was created with: create it again to see the new one.
DROP TRIGGER public.claim_history;
CREATE TRIGGER claim_history AFTER INSERT, UPDATE, DELETE ON public.claim FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';
-- A person's aliases: other names they go by, kept trimmed. An alias shares the names' uniqueness on
-- its sheet (compared without case and ignoring surrounding spaces): it equals no name or alias there.
-- `alias_key` is the form they are compared in.
CREATE TABLE person_alias (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(500) NOT NULL,
    alias_key VARCHAR(500) NOT NULL
);
CREATE UNIQUE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);

CREATE TABLE asof.person_alias AS SELECT * FROM public.person_alias WHERE FALSE;
CREATE TABLE asof_hist.person_alias AS SELECT * FROM public.person_alias WHERE FALSE;
ALTER TABLE asof_hist.person_alias ADD COLUMN h_seq BIGINT NOT NULL;
ALTER TABLE asof_hist.person_alias ADD COLUMN h_made_on DATE;
ALTER TABLE asof_hist.person_alias ADD COLUMN h_op CHAR(1) NOT NULL;
CREATE INDEX person_alias_hist_sheet ON asof_hist.person_alias (sheet_id, h_seq);
CREATE TRIGGER person_alias_history AFTER INSERT, UPDATE, DELETE ON public.person_alias FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { useVoidReasons, voidReasonsKey, type VoidReason } from './useVoidReasons';

/**
 * The sheet's void reasons and a text entry to add one. While the list is not empty, a claim is
 * voided only with a reason chosen from it; a blank reason, or one already on the list, is refused.
 */
function VoidReasonsPanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data: reasons = [] } = useVoidReasons(sheet);
  const [text, setText] = useState('');
  const [invalid, setInvalid] = useState(false);

  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (r: string) =>
      postJson<VoidReason>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons`, { reason: r, user }),
    onSuccess: async () => {
      setText('');
      await queryClient.invalidateQueries({ queryKey: voidReasonsKey(sheet) });
    },
  });

  // An error goes as soon as its form is changed or submitted again.
  const clearError = () => {
    add.reset();
    setInvalid(false);
  };

  return (
    <section data-testid="void-reasons-panel">
      <h2>Void reasons</h2>
      <form
        data-testid="void-reason-form"
        onSubmit={(e) => {
          e.preventDefault();
          const r = text.trim();
          if (r === '' || reasons.some((v) => v.reason === r)) {
            // Refused here, before anything is sent: the store and the audit file are untouched.
            add.reset();
            setInvalid(true);
            return;
          }
          setInvalid(false);
          submitOnce(() => add.mutateAsync(r));
        }}
      >
        <label>
          Reason{' '}
          <input
            data-testid="void-reason-text"
            value={text}
            onChange={(e) => {
              setText(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="void-reason-add" disabled={add.isPending}>
          Add void reason
        </button>
        {(invalid || add.isError) && (
          <span data-testid="void-reason-error" role="alert">
            {' '}
            {invalid ? 'Enter a reason not already on the list.' : 'Could not add this void reason.'}
          </span>
        )}
      </form>
      <ul data-testid="void-reason-list">
        {reasons.map((v) => (
          <li key={v.reason} data-testid={`void-reason-row-${v.reason}`}>
            {v.reason}
          </li>
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 8, Component: VoidReasonsPanel });
