import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { useVoidReasons, voidReasonsKey, type VoidReason } from './useVoidReasons';

/**
 * The sheet's void reasons and a text entry to add one. While the list is not empty, a claim is
 * voided only with a reason chosen from it; a blank reason, or one already on the list, is refused.
 */
function VoidReasonsPanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data: reasons = [] } = useVoidReasons(sheet);
  const [text, setText] = useState('');
  const [invalid, setInvalid] = useState(false);

  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (r: string) =>
      postJson<VoidReason>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons`, { reason: r, user }),
    onSuccess: async () => {
      setText('');
      await queryClient.invalidateQueries({ queryKey: voidReasonsKey(sheet) });
    },
  });

  // An error goes as soon as its form is changed or submitted again.
  const clearError = () => {
    add.reset();
    setInvalid(false);
  };

  return (
    <section data-testid="void-reasons-panel">
      <h2>Void reasons</h2>
      <form
        data-testid="void-reason-form"
        onSubmit={(e) => {
          e.preventDefault();
          const r = text.trim();
          if (r === '' || reasons.some((v) => v.reason === r)) {
            // Refused here, before anything is sent: the store and the audit file are untouched.
            add.reset();
            setInvalid(true);
            return;
          }
          setInvalid(false);
          submitOnce(() => add.mutateAsync(r));
        }}
      >
        <label>
          Reason{' '}
          <input
            data-testid="void-reason-text"
            value={text}
            onChange={(e) => {
              setText(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="void-reason-add" disabled={add.isPending}>
          Add void reason
        </button>
        {(invalid || add.isError) && (
          <span data-testid="void-reason-error" role="alert">
            {' '}
            {invalid ? 'Enter a reason not already on the list.' : 'Could not add this void reason.'}
          </span>
        )}
      </form>
      <ul data-testid="void-reason-list">
        {reasons.map((v) => (
          <li key={v.reason} data-testid={`void-reason-row-${v.reason}`}>
            {v.reason}
          </li>
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 8, Component: VoidReasonsPanel });
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated claim body. `date` is null when none was given: the sheet's today is used.
 *  `corrects` is the number of the claim a correction corrects; null for any other claim.
 *  `ref` is the external reference, trimmed; null when none was given.
 *  `tags` is the claim's tags, each trimmed and lower-cased, repeats dropped, sorted, comma separated; null when none was given. */
public record ClaimValues(BigDecimal amount, LocalDate date, String note, String corrects, String user, String ref, String tags) {
}
package net.officefloor.hq.app.rollup;

/** Who makes a change, published by the change's validating step for the steps after it. */
public record Actor(String user) {
}
import { defineSlot } from '../Slot';

/**
 * The shell's nav bar. Every page contributes its own link — the shell never lists the pages.
 * A nav link carries `data-testid="nav-<section>"` (the test contract; CLAUDE.md).
 */
export const AppNav = defineSlot('app.nav');
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/usePeople';

/** Extra column headers of the people list, one `<th>` per contribution. */
export const PersonColumns = defineSlot<{ user: string; sheet: string }>('person.columns');

/**
 * Extra cells of a person's row, one `<td>` per contribution, in the same order as their
 * PersonColumns headers. Everything kept per person (claims, ...) shows here, inside the row.
 */
export const PersonCells = defineSlot<{ user: string; sheet: string; person: Person }>('person.cells');
import { defineSlot } from '../Slot';

/**
 * The active sheet's content on the home screen. Rendered only once someone is signed in and a
 * sheet is loaded; everything kept per sheet contributes a panel here, keyed by `sheet`.
 */
export const SheetPanels = defineSlot<{ user: string; sheet: string }>('sheet.panels');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}

